-- BigQuery stored empty CSV strings as '', but COPY loads them as NULL.
-- Restore '' so dashboard SQL comparing against '' behaves the same.
DO $$
DECLARE c record;
BEGIN
  FOR c IN
    SELECT table_name, column_name FROM information_schema.columns
    WHERE table_schema = 'revops' AND data_type = 'text'
  LOOP
    EXECUTE format('UPDATE revops.%I SET %I = '''' WHERE %I IS NULL', c.table_name, c.column_name, c.column_name);
  END LOOP;
END $$;
